-- LOCAL ONLY. Full transactional package; rollback refuses source drift or operational use.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL search_path=pg_catalog;LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;SELECT pg_advisory_xact_lock(61001,1);LOCK TABLE public.folha_registos,public.folha_referencias,public.folha_referencias_historico,public.folha_avaliacoes_diarias,public.folha_historico,public.folha_gestao_historico,public.folha_conferencias_mensais,public.folha_conferencia_historico,public.folha_vencimentos,public.lancamentos_mao_obra,public.ausencias,public.quadro_equipa_permanencias,folha_privado.operacoes IN SHARE ROW EXCLUSIVE MODE;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='19a238d484fcb70c49644c079098a1173c57b0e1822f1348ceda33c671174fb0' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner AND a.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_calcular(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='99da02a985d0d2ab9031e5231da2da619c033899c69b50cf5ed6443f0201de33' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.conferencia_calcular(uuid,date)';END IF;END $functions$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
END $functions$;DO $absent$ BEGIN IF to_regprocedure('folha_privado.custo_hora_guardar_v3()') IS NOT NULL OR to_regprocedure('folha_privado.custo_hora_trilho_v3()') IS NOT NULL OR to_regprocedure('public.fn_folha_custo_hora_aprovar_v3(jsonb,boolean,text)') IS NOT NULL OR to_regprocedure('public.fn_folha_mapa_horas_v3(uuid,date)') IS NOT NULL OR to_regprocedure('public.fn_folha_custo_hora_contexto_v3(uuid)') IS NOT NULL OR to_regclass('public.folha_custos_hora_versoes') IS NOT NULL OR to_regclass('public.folha_custos_hora_historico') IS NOT NULL THEN RAISE EXCEPTION 'ADDON_PRESENT_OR_PARTIAL';END IF;END $absent$;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_horas_mapa_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_horas_mapa_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_horas_mapa_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_horas_mapa_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_horas_mapa_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;CREATE TABLE public.folha_custos_hora_versoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),colaborador_id uuid NOT NULL REFERENCES public.colaboradores(id),revision integer NOT NULL CHECK(revision>0),vigente_desde date NOT NULL CHECK(isfinite(vigente_desde)),vigente_ate date CHECK(isfinite(vigente_ate)),custo_hora numeric(12,4) NOT NULL CHECK(custo_hora>=0 AND custo_hora::text NOT IN('NaN','Infinity','-Infinity')),moeda text NOT NULL DEFAULT 'EUR' CHECK(moeda='EUR'),evidencia jsonb NOT NULL CHECK(jsonb_typeof(evidencia)='object' AND evidencia<>'{}'::jsonb),motivo text NOT NULL CHECK(length(btrim(motivo)) BETWEEN 1 AND 1000),aprovado_por uuid NOT NULL REFERENCES public.utilizadores(id),aprovado_em timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,encerrado_por uuid REFERENCES public.utilizadores(id),encerrado_em timestamptz,encerramento_request_id uuid,UNIQUE(empresa_id,colaborador_id,revision),CHECK(vigente_ate IS NULL OR vigente_ate>vigente_desde),CHECK(num_nonnulls(vigente_ate,encerrado_por,encerrado_em,encerramento_request_id) IN(0,4)));
CREATE TABLE public.folha_custos_hora_historico(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),nova_versao_id uuid NOT NULL UNIQUE REFERENCES public.folha_custos_hora_versoes(id),antes jsonb,depois jsonb NOT NULL,ator_id uuid NOT NULL REFERENCES public.utilizadores(id),at timestamptz NOT NULL DEFAULT now(),request_id uuid NOT NULL,UNIQUE(empresa_id,ator_id,request_id));ALTER TABLE public.folha_custos_hora_versoes ENABLE ROW LEVEL SECURITY;ALTER TABLE public.folha_custos_hora_historico ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.folha_custos_hora_versoes,public.folha_custos_hora_historico FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION folha_privado.custo_hora_guardar_v3() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE u public.utilizadores;r public.folha_custos_hora_versoes;
BEGIN
 IF current_user<>'postgres' OR TG_OP='DELETE' OR TG_TABLE_NAME='folha_custos_hora_historico' AND TG_OP<>'INSERT' THEN RAISE EXCEPTION 'RH_COST_PROTECTED' USING ERRCODE='42501';END IF;u:=folha_privado.ator();IF NOT folha_privado.adm_operacional() OR NEW.empresa_id<>u.empresa_id THEN RAISE EXCEPTION 'PERMISSION_DENIED: aprovação RH' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='folha_custos_hora_historico' THEN SELECT * INTO r FROM public.folha_custos_hora_versoes WHERE id=NEW.nova_versao_id;IF NEW.ator_id<>u.id OR NEW.request_id<>r.request_id OR NEW.depois->'new' IS DISTINCT FROM to_jsonb(r) THEN RAISE EXCEPTION 'RH_COST_HISTORY_INVALID';END IF;RETURN NEW;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=NEW.colaborador_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND (NEW.id,NEW.empresa_id,NEW.colaborador_id,NEW.revision,NEW.vigente_desde,NEW.custo_hora,NEW.moeda,NEW.evidencia,NEW.motivo,NEW.aprovado_por,NEW.aprovado_em,NEW.request_id) IS DISTINCT FROM (OLD.id,OLD.empresa_id,OLD.colaborador_id,OLD.revision,OLD.vigente_desde,OLD.custo_hora,OLD.moeda,OLD.evidencia,OLD.motivo,OLD.aprovado_por,OLD.aprovado_em,OLD.request_id) THEN RAISE EXCEPTION 'RH_COST_VERSION_IMMUTABLE';END IF;
 IF TG_OP='UPDATE' AND OLD.vigente_ate IS NOT NULL THEN RAISE EXCEPTION 'RH_COST_VERSION_CLOSED';END IF;
 IF TG_OP='INSERT' AND (NEW.aprovado_por<>u.id OR NEW.aprovado_em IS DISTINCT FROM now() OR NEW.revision<>(SELECT coalesce(max(revision),0)+1 FROM public.folha_custos_hora_versoes WHERE empresa_id=u.empresa_id AND colaborador_id=NEW.colaborador_id)) THEN RAISE EXCEPTION 'RH_COST_REVISION_INVALID';END IF;
 IF NEW.vigente_ate IS NOT NULL AND (NEW.encerrado_por<>u.id OR NEW.encerrado_em IS DISTINCT FROM now()) THEN RAISE EXCEPTION 'RH_COST_CLOSE_INVALID';END IF;
 IF EXISTS(SELECT 1 FROM public.folha_custos_hora_versoes prior WHERE prior.id<>NEW.id AND prior.colaborador_id=NEW.colaborador_id AND daterange(prior.vigente_desde,prior.vigente_ate,'[)')&&daterange(NEW.vigente_desde,NEW.vigente_ate,'[)')) THEN RAISE EXCEPTION 'RH_COST_OVERLAP';END IF;RETURN NEW;
END $guard$;
CREATE FUNCTION folha_privado.custo_hora_trilho_v3() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $trail$
BEGIN IF TG_OP='INSERT' THEN IF NOT EXISTS(SELECT 1 FROM public.folha_custos_hora_historico WHERE nova_versao_id=NEW.id AND depois->'new'=to_jsonb(NEW) AND request_id=NEW.request_id) THEN RAISE EXCEPTION 'RH_COST_HISTORY_REQUIRED';END IF;ELSE IF NOT EXISTS(SELECT 1 FROM public.folha_custos_hora_historico WHERE depois->'closed_previous'=to_jsonb(NEW) AND request_id=NEW.encerramento_request_id) THEN RAISE EXCEPTION 'RH_COST_HISTORY_REQUIRED';END IF;END IF;RETURN NULL;END $trail$;
CREATE TRIGGER folha_custo_hora_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_custos_hora_versoes FOR EACH ROW EXECUTE FUNCTION folha_privado.custo_hora_guardar_v3();CREATE TRIGGER folha_custo_hora_historico_guardar BEFORE INSERT OR UPDATE OR DELETE ON public.folha_custos_hora_historico FOR EACH ROW EXECUTE FUNCTION folha_privado.custo_hora_guardar_v3();CREATE CONSTRAINT TRIGGER folha_custo_hora_trilho AFTER INSERT OR UPDATE ON public.folha_custos_hora_versoes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION folha_privado.custo_hora_trilho_v3();
CREATE FUNCTION public.fn_folha_custo_hora_aprovar_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $approve$
DECLARE u public.utilizadores;p uuid:=(p_dados->>'person_id')::uuid;d date:=(p_dados->>'effective_from')::date;req uuid:=(p_dados->>'request_id')::uuid;old public.folha_custos_hora_versoes;closed public.folha_custos_hora_versoes;n public.folha_custos_hora_versoes;payload jsonb;token text;op folha_privado.operacoes;result jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();IF NOT folha_privado.adm_operacional() THEN RAISE EXCEPTION 'PERMISSION_DENIED: RH' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador/data' USING ERRCODE='42501';END IF;
 IF req IS NULL OR d IS NULL OR NOT isfinite(d) OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR jsonb_typeof(p_dados->'hourly_cost') IS DISTINCT FROM 'number' OR (p_dados->>'hourly_cost')::numeric<0 OR (p_dados->>'hourly_cost')::numeric<>round((p_dados->>'hourly_cost')::numeric,4) OR jsonb_typeof(p_dados->'evidence') IS DISTINCT FROM 'object' OR p_dados->'evidence'='{}'::jsonb OR nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'RH_COST_PROOF_REQUIRED';END IF;
 payload:=jsonb_build_object('action','rh_cost_approve','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 SELECT * INTO old FROM public.folha_custos_hora_versoes WHERE empresa_id=u.empresa_id AND colaborador_id=p ORDER BY revision DESC LIMIT 1 FOR UPDATE;IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(old.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;IF old.id IS NOT NULL AND d<=old.vigente_desde THEN RAISE EXCEPTION 'RH_COST_EFFECTIVE_DATE_ORDER';END IF;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'before',to_jsonb(old))::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token);END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 IF old.id IS NOT NULL THEN UPDATE public.folha_custos_hora_versoes SET vigente_ate=d,encerrado_por=u.id,encerrado_em=now(),encerramento_request_id=req WHERE id=old.id RETURNING * INTO closed;END IF;
 INSERT INTO public.folha_custos_hora_versoes(empresa_id,colaborador_id,revision,vigente_desde,custo_hora,evidencia,motivo,aprovado_por,request_id) VALUES(u.empresa_id,p,coalesce(old.revision,0)+1,d,(p_dados->>'hourly_cost')::numeric,p_dados->'evidence',p_dados->>'reason',u.id,req) RETURNING * INTO n;
 INSERT INTO public.folha_custos_hora_historico(empresa_id,nova_versao_id,antes,depois,ator_id,request_id) VALUES(u.empresa_id,n.id,to_jsonb(old),jsonb_build_object('closed_previous',to_jsonb(closed),'new',to_jsonb(n)),u.id,req);
 result:=jsonb_build_object('version',3,'committed',true,'request_id',req,'rate_id',n.id,'revision',n.revision,'financial_effect',false);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,result,now());RETURN result;
END $approve$;
CREATE FUNCTION public.fn_folha_mapa_horas_v3(p_obra_id uuid,p_competencia date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $map$
DECLARE u public.utilizadores;r jsonb;g record;f jsonb;c public.folha_conferencias_mensais;a public.folha_avaliacoes_diarias;rate public.folha_custos_hora_versoes;ref jsonb;approval_cache jsonb:='{}';source_ok boolean;consolidated boolean;expected integer;actual integer;status text;amount numeric;money boolean;groups jsonb:='[]';minutes_provisional integer:=0;minutes_consolidated integer:=0;minutes_external integer:=0;known_amount numeric:=0;unknown_cost integer:=0;known_days integer:=0;
BEGIN
 u:=folha_privado.ator();IF p_competencia IS NULL OR NOT isfinite(p_competencia) OR extract(day FROM p_competencia)<>1 THEN RAISE EXCEPTION 'MONTH_REQUIRED';END IF;r:=public.fn_folha_relatorio_horas_v3(p_obra_id,p_competencia,(p_competencia+interval '1 month')::date-1,NULL,NULL);money:=folha_privado.admin();
 FOR g IN SELECT x->>'kind' kind,(x->>'person_id')::uuid person_id,(x->>'date')::date date,jsonb_agg(x ORDER BY x->>'id') records,sum((x->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(r->'records') x GROUP BY x->>'kind',x->>'person_id',x->>'date' ORDER BY x->>'date',x->>'person_id' LOOP
  amount:=NULL;status:='horas_apenas';consolidated:=false;rate:=NULL;
  IF g.kind='external' THEN minutes_external:=minutes_external+g.minutes;
  ELSE
   IF NOT(approval_cache ? g.person_id::text) THEN SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND competencia=p_competencia;source_ok:=false;IF c.estado='validada_para_integracao' AND c.fingerprint=c.validacao_fingerprint THEN source_ok:=(folha_privado.conferencia_calcular(g.person_id,p_competencia)->>'fingerprint')=c.fingerprint;END IF;approval_cache:=approval_cache||jsonb_build_object(g.person_id::text,source_ok);END IF;
   SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND competencia=p_competencia;
   consolidated:=coalesce((approval_cache->>g.person_id::text)::boolean,false) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(g.records) fact WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.snapshot->'days') day CROSS JOIN LATERAL jsonb_array_elements(day->'facts') item WHERE item->>'id'=fact->>'id' AND item->>'revision'=fact->>'revision'));
   IF consolidated THEN minutes_consolidated:=minutes_consolidated+g.minutes;ELSE minutes_provisional:=minutes_provisional+g.minutes;END IF;
   SELECT * INTO a FROM public.folha_avaliacoes_diarias WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND data=g.date;IF a.referencia_estado='capturada' THEN expected:=a.expected_minutes;ELSE ref:=folha_privado.diaria_referencia(g.person_id,g.date);expected:=CASE WHEN ref->>'referencia_estado'='capturada' THEN (ref->>'expected_minutes')::integer END;END IF;
   SELECT coalesce(sum(x.minutes),0)::integer INTO actual FROM (SELECT minutes FROM public.folha_registos WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND data=g.date UNION ALL SELECT minutes FROM public.folha_referencias WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND data=g.date) x;
   IF expected IS NOT NULL AND actual>expected THEN status:='pendente_de_valorizacao';
   ELSIF expected IS NULL THEN status:='referencia_diaria_pendente';
   ELSIF EXISTS(SELECT 1 FROM jsonb_array_elements(g.records) x WHERE coalesce((x->>'association_pending')::boolean,false) OR (x->>'open')::boolean) THEN status:='factos_pendentes';
   ELSIF NOT money THEN status:='horas_apenas';
   ELSE SELECT * INTO rate FROM public.folha_custos_hora_versoes WHERE empresa_id=u.empresa_id AND colaborador_id=g.person_id AND vigente_desde<=g.date AND (vigente_ate IS NULL OR vigente_ate>g.date);IF rate.id IS NULL THEN status:='custo_hora_rh_pendente';ELSE status:='estimativa_provisoria';amount:=round(g.minutes*rate.custo_hora/60,2);known_amount:=known_amount+amount;known_days:=known_days+1;END IF;END IF;
   IF amount IS NULL THEN unknown_cost:=unknown_cost+1;END IF;
  END IF;
  groups:=groups||jsonb_build_array(jsonb_build_object('person_id',g.person_id,'kind',g.kind,'date',g.date,'minutes',g.minutes,'records',g.records,'consolidated',consolidated,'valuation_status',status,'provisional_estimate',amount,'rate_id',CASE WHEN amount IS NOT NULL THEN rate.id END,'rate_revision',CASE WHEN amount IS NOT NULL THEN rate.revision END,'valuation_blocks_rh',false));
 END LOOP;
 RETURN jsonb_build_object('version',3,'work_id',p_obra_id,'month',p_competencia,'groups',groups,'provisional_minutes',minutes_provisional,'consolidated_minutes',minutes_consolidated,'external_minutes',minutes_external,'provisional_estimate',CASE WHEN money AND unknown_cost=0 AND known_days>0 THEN known_amount END,'known_provisional_estimate',CASE WHEN money AND known_days>0 THEN known_amount END,'valuation_scope','internal_hours_only','pending_valuation_days',unknown_cost,'financial_effect',false,'legacy_costs_included',false,'he_cost_calculated',false);
END $map$;
